create or replace function public.create_project_with_services(p_client_id uuid,p_name text,p_domain text,p_start_date date,p_billing_preference public.billing_preference,p_is_white_label boolean,p_description text,p_services jsonb)returns uuid language plpgsql security invoker set search_path=''as $$declare project_id uuid;item jsonb;seen uuid[]:=array[]::uuid[];service_id uuid;begin if not(public.has_permission('projects.manage')and public.has_permission('finance.manage'))then raise exception'insufficient_permission'using errcode='42501';end if;if jsonb_array_length(p_services)<1 then raise exception'project_requires_service';end if;insert into public.projects(client_id,name,domain,start_date,billing_preference,is_white_label,description,created_by,updated_by)values(p_client_id,p_name,nullif(trim(p_domain),''),p_start_date,p_billing_preference,p_is_white_label,p_description,auth.uid(),auth.uid())returning id into project_id;for item in select*from jsonb_array_elements(p_services)loop service_id:=(item->>'service_id')::uuid;if service_id=any(seen)then raise exception'duplicate_service';end if;seen:=array_append(seen,service_id);insert into public.project_services(project_id,service_id,periodicity,currency,billing_preference,start_date,payment_term_days,status,notes,created_by,updated_by)values(project_id,service_id,(item->>'periodicity')::public.service_periodicity,(item->>'currency')::public.currency_code,p_billing_preference,p_start_date,(item->>'payment_term_days')::integer,'active',nullif(item->>'notes',''),auth.uid(),auth.uid())returning id into service_id;insert into public.project_service_prices(project_service_id,net_price,vat_rate,currency,effective_from,created_by)values(service_id,(item->>'net_price')::numeric,(item->>'vat_rate')::numeric,(item->>'currency')::public.currency_code,p_start_date,auth.uid());end loop;return project_id;end$$;
create or replace function public.update_project_with_new_services(p_project_id uuid,p_client_id uuid,p_name text,p_domain text,p_start_date date,p_billing_preference public.billing_preference,p_is_white_label boolean,p_description text,p_services jsonb)returns void language plpgsql security invoker set search_path=''as $$declare item jsonb;new_project_service uuid;selected_service_id uuid;begin if not(public.has_permission('projects.manage')and public.has_permission('finance.manage'))then raise exception'insufficient_permission'using errcode='42501';end if;update public.projects set client_id=p_client_id,name=p_name,domain=nullif(trim(p_domain),''),start_date=p_start_date,billing_preference=p_billing_preference,is_white_label=p_is_white_label,description=p_description,updated_by=auth.uid()where id=p_project_id;if not found then raise exception'project_not_found';end if;update public.project_services set billing_preference=p_billing_preference,updated_by=auth.uid()where project_id=p_project_id and status='active';for item in select*from jsonb_array_elements(coalesce(p_services,'[]'::jsonb))loop selected_service_id:=(item->>'service_id')::uuid;if exists(select 1 from public.project_services ps where ps.project_id=p_project_id and ps.service_id=selected_service_id and ps.status='active')then raise exception'service_already_exists';end if;insert into public.project_services(project_id,service_id,periodicity,currency,billing_preference,start_date,payment_term_days,status,notes,created_by,updated_by)values(p_project_id,selected_service_id,(item->>'periodicity')::public.service_periodicity,(item->>'currency')::public.currency_code,p_billing_preference,p_start_date,(item->>'payment_term_days')::integer,'active',nullif(item->>'notes',''),auth.uid(),auth.uid())returning id into new_project_service;insert into public.project_service_prices(project_service_id,net_price,vat_rate,currency,effective_from,created_by)values(new_project_service,(item->>'net_price')::numeric,(item->>'vat_rate')::numeric,(item->>'currency')::public.currency_code,p_start_date,auth.uid());end loop;end$$;
grant execute on function public.create_project_with_services(uuid,text,text,date,public.billing_preference,boolean,text,jsonb)to authenticated;
grant execute on function public.update_project_with_new_services(uuid,uuid,text,text,date,public.billing_preference,boolean,text,jsonb)to authenticated;
